message:
Running command: bash -lc 'set -euo pipefail;
ts=$(date +%F_%H%M%S);
workdir=/workspace/audit; mkdir -p "$workdir";
backup_dir="$workdir/etc_backup_$ts"; mkdir -p "$backup_dir";
plan="$workdir/delete_plan_$ts.txt"; log="$workdir/delete_run_$ts.log";

# Build unowned list
unowned=$(mktemp); filtered=$(mktemp);
find /etc -xdev \( -type f -o -type l \) -print \
  | while IFS= read -r f; do dpkg -S "$f" >/dev/null 2>&1 || echo "$f"; done > "$unowned";

# Exclude critical/generated/managed paths
cat "$unowned" \
  | grep -Ev "^/etc/ssl/|^/etc/pki/|^/etc/ca-certificates|^/etc/alternatives/|^/etc/systemd/|^/etc/rc[0-6S]\\.d/|^/etc/init/|^/etc/machine-id$|^/etc/(hostname|hosts|resolv\\.conf|timezone|localtime|ld\\.so\\.cache|\\.pwd\\.lock|subuid|subgid|environment|shells)$|^/etc/(group-|gshadow-|passwd-|shadow-)$" \
  | sort -u > "$filtered";

count=$(wc -l < "$filtered" | tr -d " ");
{
  echo "=== Deletion plan generated at $ts ===";
  echo "Backup directory: $backup_dir";
  echo "Candidates (unowned, after safe exclusions): $count";
  echo;
  cat "$filtered";
} > "$plan";

# Backup and delete each candidate
if [ "$count" -gt 0 ]; then
  echo "Backing up and deleting $count candidate files..." | tee -a "$log";
  while IFS= read -r f; do
    # Ensure destination path exists and copy preserving attributes
    dest="$backup_dir$f"; mkdir -p "$(dirname "$dest")";
    cp -a --preserve=all "$f" "$dest" 2>/dev/null || cp -a "$f" "$dest" || true;
    rm -f -- "$f";
    echo "deleted: $f" >> "$log";
  done < "$filtered";
else
  echo "No unowned candidates to delete after exclusions." | tee -a "$log";
fi

rm -f "$unowned" "$filtered";

# Refresh audit and show summary
if [ -x /workspace/etc_audit.sh ]; then /workspace/etc_audit.sh "$workdir" >/dev/null; fi;
printf "Plan: %s\nLog: %s\nBackup: %s\nAudit: %s\n" "$plan" "$log" "$backup_dir" "$workdir/etc_audit_report.txt";
# Show a brief diff: list of deleted files
echo "--- Deleted entries (last 50) ---"; tail -n 50 "$log" || true;

